/**
 * Runtime contracts and helpers for SDKs generated by Tungsten.
 *
 * Generated clients call {@link ClientCore} with descriptors; applications can
 * use the same core directly. Calls return {@link Result} values, while
 * {@link unwrap} and {@link throwing} provide exception-based access.
 *
 * This entry point uses Web APIs and does not import the Node filesystem
 * adapter. Import FileIdempotencyStore separately from
 * `@elysra/tungsten-runtime/node` when keys must persist in a local file.
 *
 * @module
 */

export * from "./types.js";
export { ClientCore } from "./client.js";
export { ANY_EVENT, EventStream, type CollectOptions, type EventHandler, type StreamEvent, type StreamResult } from "./streams.js";
export { DEFAULT_MAX_EVENT_BYTES, SseParser, type SseEvent } from "./sse.js";
export { MemoryIdempotencyStore } from "./idempotency.js";
export { RequestScheduler, type Permit, type Rejection, type RetryBudgetOptions, type SchedulerOptions, type SchedulerStats } from "./scheduler.js";
export {
  generatePkce,
  MemoryTokenStore,
  OAuthFlow,
  pkceChallenge,
  type AuthorizationUrlParams,
  type AuthorizationAttempt,
  type IssuerDefense,
  type LowLevelAuthorizationUrlParams,
  type LowLevelExchangeCodeParams,
  type ExchangeCodeParams,
  type OAuthResult,
  type Pkce,
  type StoredToken,
  type TokenInfo,
  type TokenStore,
} from "./oauth.js";
export { TungstenError, unwrap, throwing, type Throwing } from "./errors.js";
export { defineApi, defineMacro, defineOperation } from "./define.js";
export { evaluatePredicate } from "./expr.js";
export { DEFAULT_RETRYABLE } from "./envelope.js";
export { CONFIRMATION_TTL_MS } from "./confirm.js";
export { RUNTIME_VERSION } from "./version.js";
export { isBinaryInput, type BinaryInput, type NamedBinary } from "./util.js";

/** Capability handshake used by generated imported descriptors. Older runtimes
 * do not export it, so loading scoped reviews fails before any call. */
export function requireImportPolicyV1(): void {}

/** Older runtimes must reject SDKs that require disabled redirects. */
export function requireRedirectPolicyV1(): void {}
